// ── PROCEDURAL WEAPON SPRITES ──
// Generates simple SVG weapon overlays for races that lack pixel-art sprites.
// Positioned at each race's hand anchor points within 64×64 canvas.

const RACE_WEAPON_ANCHORS = {
  // [leftX, leftY, rightX, rightY] — where weapon grips on 64×64 canvas
  // All weapons render at scale 1.0 — only position changes per race
  'homosapien':    [10, 38, 50, 38],
  'nordic':        [10, 38, 50, 38],
  'annunaki':      [10, 38, 50, 38],
  'skinwalker':    [10, 38, 50, 38],
  'giant':         [8,  40, 52, 40],
  'bigfoot':       [8,  38, 52, 38],
  'angel':         [10, 38, 50, 38],
  'seraphim':      [10, 38, 50, 38],
  'demon':         [10, 36, 50, 36],
  'succubus':      [10, 38, 50, 38],
  'zombie':        [10, 38, 50, 38],
  'skeleton':      [10, 38, 50, 38],
  'reptilian':     [10, 38, 50, 38],
  'android':       [10, 38, 50, 38],
  'robot':         [10, 38, 50, 38],
  'mech':          [8,  38, 52, 38],
  'grey':          [14, 38, 46, 38],
  'martian':       [14, 38, 46, 38],
  'fairy':         [18, 38, 42, 38],
  'ai':            [14, 36, 46, 36],
  'ghost':         [12, 38, 48, 38],
  'shadow entity': [12, 38, 48, 38],
  'orb of light':  [16, 36, 44, 36],
};

// SVG weapon shape generators — return SVG element string
const WEAPON_SVG_SHAPES = {
  iron_sword(x, y, s) {
    const bw = 4*s, bh = 24*s, gw = 12*s, gh = 3*s, hw = 3*s, hh = 7*s;
    return `<rect x="${x-bw/2}" y="${y-bh}" width="${bw}" height="${bh}" rx="1" fill="#b0bec5" stroke="#78909c" stroke-width="0.7"/>` +
           `<rect x="${x-gw/2}" y="${y-2*s}" width="${gw}" height="${gh}" rx="1" fill="#8d6e63"/>` +
           `<rect x="${x-hw/2}" y="${y}" width="${hw}" height="${hh}" rx="1" fill="#5d4037"/>`;
  },
  iron_shield(x, y, s) {
    const w = 16*s, h = 20*s;
    return `<rect x="${x-w/2}" y="${y-h/2}" width="${w}" height="${h}" rx="${4*s}" fill="#607d8b" stroke="#455a64" stroke-width="1.2"/>` +
           `<rect x="${x-2.5*s}" y="${y-5*s}" width="${5*s}" height="${10*s}" rx="1" fill="#ffd54f" opacity="0.7"/>` +
           `<rect x="${x-5*s}" y="${y-2.5*s}" width="${10*s}" height="${5*s}" rx="1" fill="#ffd54f" opacity="0.7"/>`;
  },
  revolver_r(x, y, s) {
    const bw = 18*s, bh = 4*s, gh = 8*s, gw = 4*s;
    return `<rect x="${x-2*s}" y="${y-bh/2}" width="${bw}" height="${bh}" rx="1.5" fill="#546e7a" stroke="#37474f" stroke-width="0.7"/>` +
           `<rect x="${x}" y="${y+1*s}" width="${gw}" height="${gh}" rx="1" fill="#4e342e"/>` +
           `<circle cx="${x+14*s}" cy="${y}" r="${2*s}" fill="#37474f"/>`;
  },
  revolver_l(x, y, s) {
    const bw = 18*s, bh = 4*s, gh = 8*s, gw = 4*s;
    return `<rect x="${x-16*s}" y="${y-bh/2}" width="${bw}" height="${bh}" rx="1.5" fill="#546e7a" stroke="#37474f" stroke-width="0.7"/>` +
           `<rect x="${x-4*s}" y="${y+1*s}" width="${gw}" height="${gh}" rx="1" fill="#4e342e"/>` +
           `<circle cx="${x-14*s}" cy="${y}" r="${2*s}" fill="#37474f"/>`;
  },
  arcane_staff(x, y, s) {
    const sw = 3*s, sh = 30*s, orb = 5*s;
    return `<rect x="${x-sw/2}" y="${y-sh}" width="${sw}" height="${sh}" rx="1" fill="#6d4c41"/>` +
           `<circle cx="${x}" cy="${y-sh+2*s}" r="${orb}" fill="#9c27b0" opacity="0.85"/>` +
           `<circle cx="${x}" cy="${y-sh+2*s}" r="${2.5*s}" fill="#e1bee7" opacity="0.6"/>`;
  },
  healing_staff(x, y, s) {
    const sw = 3*s, sh = 28*s, gem = 4.5*s;
    return `<rect x="${x-sw/2}" y="${y-sh}" width="${sw}" height="${sh}" rx="1" fill="#a1887f"/>` +
           `<circle cx="${x}" cy="${y-sh+2*s}" r="${gem}" fill="#26a69a" opacity="0.85"/>` +
           `<circle cx="${x}" cy="${y-sh+2*s}" r="${2.2*s}" fill="#80cbc4" opacity="0.6"/>`;
  },
  combat_knife(x, y, s) {
    const bw = 4*s, bh = 14*s, hw = 3*s, hh = 6*s;
    return `<rect x="${x-bw/2}" y="${y-bh}" width="${bw}" height="${bh}" rx="1" fill="#90a4ae" stroke="#607d8b" stroke-width="0.7"/>` +
           `<rect x="${x-hw/2}" y="${y}" width="${hw}" height="${hh}" rx="1" fill="#3e2723"/>`;
  },
  frag_bomb(x, y, s) {
    const r = 7*s;
    return `<circle cx="${x}" cy="${y}" r="${r}" fill="#455a64" stroke="#37474f" stroke-width="1.2"/>` +
           `<rect x="${x-1.5*s}" y="${y-r-4*s}" width="${3*s}" height="${5*s}" rx="1" fill="#8d6e63"/>` +
           `<line x1="${x}" y1="${y-r-4*s}" x2="${x+4*s}" y2="${y-r-8*s}" stroke="#ff9800" stroke-width="${2*s}" stroke-linecap="round"/>`;
  }
};

// Map equipment IDs to weapon shape keys
const EQUIP_TO_WEAPON = {
  'iron_sword': 'iron_sword',
  'iron_sword_l': 'iron_sword',
  'iron_shield': 'iron_shield',
  'iron_shield_r': 'iron_shield',
  'revolver_r': 'revolver_r',
  'revolver_l': 'revolver_l',
  'arcane_staff': 'arcane_staff',
  'arcane_staff_r': 'arcane_staff',
  'healing_staff': 'healing_staff',
  'healing_staff_l': 'healing_staff',
  'combat_knife': 'combat_knife',
  'combat_knife_l': 'combat_knife',
  'frag_bomb': 'frag_bomb',
  'frag_bomb_r': 'frag_bomb'
};

// Generate SVG weapon sprite as data URI
function generateWeaponSvg(weaponId, x, y, scale) {
  const shapeKey = EQUIP_TO_WEAPON[weaponId];
  if (!shapeKey || !WEAPON_SVG_SHAPES[shapeKey]) return null;
  const shapes = WEAPON_SVG_SHAPES[shapeKey](x, y, scale);
  const svg = `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 64 64" width="64" height="64">${shapes}</svg>`;
  return 'data:image/svg+xml;utf8,' + encodeURIComponent(svg);
}

// Auto-populate EQUIP_SPRITES with generated weapons
(function populateWeaponSprites() {
  const leftHandItems = new Set(['iron_shield', 'iron_shield_r', 'revolver_l', 'arcane_staff', 'arcane_staff_r', 'healing_staff_l', 'combat_knife_l', 'frag_bomb', 'frag_bomb_r']);
  // Wait — iron_shield_r is handR but uses the shield shape which draws centered. Same for arcane_staff_r.
  // The 'isLeft' flag controls which anchor point (lx,ly vs rx,ry) to use.
  // Items with slot handL should use left anchor, slot handR should use right anchor.
  const handLItems = new Set(['iron_shield', 'revolver_l', 'arcane_staff', 'healing_staff_l', 'combat_knife_l', 'frag_bomb']);

  // Races that have ZERO weapon rendering without generation
  const racesNeedingAllWeapons = ['ai', 'fairy', 'ghost', 'grey', 'martian', 'orb of light', 'shadow entity'];
  // New mirrored items that have no pixel art for ANY race
  const newMirroredItems = ['iron_sword_l', 'iron_shield_r', 'arcane_staff_r', 'healing_staff_l', 'combat_knife_l', 'frag_bomb_r'];
  const originalWeapons = ['iron_sword', 'iron_shield', 'revolver_r', 'revolver_l', 'arcane_staff', 'healing_staff', 'combat_knife', 'frag_bomb'];
  const allRaces = Object.keys(RACE_WEAPON_ANCHORS);
  const s = 1.0; // uniform weapon scale

  // Generate original weapons for races with no compat
  for (const race of racesNeedingAllWeapons) {
    const anchor = RACE_WEAPON_ANCHORS[race];
    if (!anchor) continue;
    const [lx, ly, rx, ry] = anchor;
    for (const wid of originalWeapons) {
      const key = race + '_' + wid;
      if (EQUIP_SPRITES[key]) continue;
      const isLeft = handLItems.has(wid);
      const svg = generateWeaponSvg(wid, isLeft ? lx : rx, isLeft ? ly : ry, s);
      if (svg) EQUIP_SPRITES[key] = svg;
    }
  }

  // Generate mirrored variants for ALL races (no pixel art exists for these)
  for (const race of allRaces) {
    const anchor = RACE_WEAPON_ANCHORS[race];
    if (!anchor) continue;
    const [lx, ly, rx, ry] = anchor;
    for (const wid of newMirroredItems) {
      const key = race + '_' + wid;
      if (EQUIP_SPRITES[key]) continue;
      const isLeft = handLItems.has(wid);
      const svg = generateWeaponSvg(wid, isLeft ? lx : rx, isLeft ? ly : ry, s);
      if (svg) EQUIP_SPRITES[key] = svg;
    }
  }
})();

// ── EQUIPMENT RACE COMPATIBILITY ──
// Maps races to a fallback race whose equipment sprites they can reuse,
// plus which equipment slots are compatible (based on body proportions).
// 'all' = every slot. Otherwise array of compatible slots.
// Races not listed here have no fallback — equipment won't render.
const EQUIP_RACE_COMPAT = {
  // Identical proportions & skin tone — full reuse
  'nordic':     { fallback: 'homosapien', slots: 'all' },
  'annunaki':   { fallback: 'homosapien', slots: 'all' },
  'skinwalker': { fallback: 'homosapien', slots: 'all' },

  // Humanoid frame, different skin — weapons + head + boots fit naturally
  'zombie':     { fallback: 'homosapien', slots: ['head', 'handL', 'handR', 'boots'] },
  'skeleton':   { fallback: 'homosapien', slots: ['head', 'handL', 'handR', 'boots'] },
  'demon':      { fallback: 'homosapien', slots: ['head', 'handL', 'handR'] },
  'succubus':   { fallback: 'homosapien', slots: ['head', 'handL', 'handR'] },
  'angel':      { fallback: 'homosapien', slots: ['head', 'handL', 'handR'] },
  'seraphim':   { fallback: 'homosapien', slots: ['head', 'handL', 'handR'] },

  // Mechanical body — weapons only (held items look fine on any frame)
  'android':    { fallback: 'homosapien', slots: ['handL', 'handR'] },
  'robot':      { fallback: 'homosapien', slots: ['handL', 'handR'] },
  'mech':       { fallback: 'homosapien', slots: ['handL', 'handR'] },

  // Large humanoid — weapons only (armor/hats too small)
  'bigfoot':    { fallback: 'homosapien', slots: ['handL', 'handR'] },
  'giant':      { fallback: 'homosapien', slots: ['handL', 'handR'] },

  // Alien proportions — weapons only (thin limbs, heads too different)
  'reptilian':  { fallback: 'homosapien', slots: ['handL', 'handR'] },
};
// Incompatible (no fallback): ai, fairy, ghost, grey, martian,
// orb of light, shadow entity — body shape too different or non-corporeal

// ── SPRITE RESOLVER ──
// Looks up race-specific equipment sprite. Falls back to compatible race if available.
function resolveEquipSprite(race, itemId) {
  if (!race || !itemId) return null;

  // Direct lookup: race-specific sprite exists
  const directKey = race + '_' + itemId;
  if (EQUIP_SPRITES[directKey]) return EQUIP_SPRITES[directKey];

  // Fallback: check compatibility map
  const compat = EQUIP_RACE_COMPAT[race];
  if (!compat) return null;

  // Check if this item's slot is compatible with this race
  const def = (typeof EQUIP_DEFS !== 'undefined') ? EQUIP_DEFS[itemId] : null;
  if (def && compat.slots !== 'all') {
    if (!compat.slots.includes(def.slot)) return null;
  }

  const fallbackKey = compat.fallback + '_' + itemId;
  return EQUIP_SPRITES[fallbackKey] || null;
}
// ── TERRAIN TILE SPRITES ──
