// Utility: generate SVG data URI from inner content
function _equipSvg(inner) {
  return 'data:image/svg+xml;utf8,' + encodeURIComponent(
    '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 64 64" width="64" height="64" shape-rendering="crispEdges">' + inner + '</svg>'
  );
}

// ── HEAD EQUIPMENT SVG GENERATORS ──
const HEAD_SVG_GEN = {
  plate_helm(r) {
    const {cx,cy,w,h} = r.head; const s = r.scale;
    const hw = Math.round(w*s*1.1), hh = Math.round(h*s*0.9);
    const x = cx-hw/2, y = cy-hh/2-2*s;
    return _equipSvg(
      `<rect x="${x}" y="${y+2}" width="${hw}" height="${hh}" rx="2" fill="#788898" stroke="#505868" stroke-width="1"/>` +
      `<rect x="${x+2}" y="${y}" width="${hw-4}" height="${3*s}" rx="1" fill="#687888" stroke="#485060" stroke-width="0.7"/>` +
      `<rect x="${cx-2*s}" y="${y-1}" width="${4*s}" height="${hh+3}" rx="1" fill="#e04040" opacity="0.85"/>` +
      `<rect x="${x+1}" y="${cy-1}" width="${hw-2}" height="${2.5*s}" rx="1" fill="#404858" opacity="0.7"/>` +
      `<rect x="${x+2}" y="${y+3}" width="${hw/3}" height="${2}" fill="rgba(200,220,240,0.3)"/>`
    );
  },
  wide_brim_hat(r) {
    const {cx,cy,w,h} = r.head; const s = r.scale;
    const brimW = Math.round(w*s*1.5), crownW = Math.round(w*s*0.7), crownH = Math.round(h*s*0.55);
    const brimY = cy - h*s*0.25;
    return _equipSvg(
      `<rect x="${cx-crownW/2}" y="${brimY-crownH}" width="${crownW}" height="${crownH}" rx="2" fill="#6b4226" stroke="#4a2e18" stroke-width="0.8"/>` +
      `<rect x="${cx-brimW/2}" y="${brimY-2}" width="${brimW}" height="${3*s}" rx="1" fill="#7a4e2e" stroke="#4a2e18" stroke-width="0.8"/>` +
      `<rect x="${cx-crownW/2+1}" y="${brimY-2}" width="${crownW-2}" height="${2}" fill="#96623a" opacity="0.5"/>` +
      `<rect x="${cx-crownW/2+1}" y="${brimY-crownH+2}" width="${crownW-2}" height="${2}" rx="1" fill="#503018" opacity="0.4"/>`
    );
  },
  arcane_hood(r) {
    const {cx,cy,w,h} = r.head; const s = r.scale;
    const hw = Math.round(w*s*1.15), hh = Math.round(h*s*1.1);
    const x = cx-hw/2, y = cy-hh/2-2*s;
    return _equipSvg(
      `<path d="M${cx} ${y-3*s} L${x-1} ${y+hh+1} L${x+hw+1} ${y+hh+1} Z" fill="#2a1848" stroke="#1a0c30" stroke-width="1"/>` +
      `<path d="M${cx} ${y-3*s} L${x+2} ${y+hh-2} L${x+hw-2} ${y+hh-2} Z" fill="#38205a" opacity="0.6"/>` +
      `<rect x="${x+2}" y="${y+hh-4}" width="${hw-4}" height="${4}" fill="#0a0418" opacity="0.6"/>` +
      `<rect x="${cx-1}" y="${y-2*s}" width="${2}" height="${3*s}" fill="#9060c0" opacity="0.6"/>`
    );
  },
  gold_circlet(r) {
    const {cx,cy,w,h} = r.head; const s = r.scale;
    const cw = Math.round(w*s*1.05);
    const bandY = cy - h*s*0.2;
    return _equipSvg(
      `<rect x="${cx-cw/2}" y="${bandY-1}" width="${cw}" height="${3*s}" rx="1" fill="#d4a828" stroke="#a07818" stroke-width="0.7"/>` +
      `<rect x="${cx-2*s}" y="${bandY-2*s}" width="${4*s}" height="${4*s}" rx="${2*s}" fill="#28a8a0" stroke="#d4a828" stroke-width="1"/>` +
      `<rect x="${cx-1}" y="${bandY-1*s}" width="${2}" height="${2}" fill="#80e8e0" opacity="0.7"/>` +
      `<rect x="${cx-cw/2+2}" y="${bandY}" width="${3}" height="${2}" fill="#f0d050" opacity="0.4"/>` +
      `<rect x="${cx+cw/2-5}" y="${bandY}" width="${3}" height="${2}" fill="#f0d050" opacity="0.4"/>`
    );
  },
  tactical_visor(r) {
    const {cx,cy,w,h} = r.head; const s = r.scale;
    const vw = Math.round(w*s*1.0), vh = Math.round(3.5*s);
    const vy = cy - h*s*0.1;
    return _equipSvg(
      `<rect x="${cx-vw/2}" y="${vy}" width="${vw}" height="${vh}" rx="2" fill="#1a2a3a" stroke="#0a1520" stroke-width="0.8"/>` +
      `<rect x="${cx-vw/2+2}" y="${vy+1}" width="${vw-4}" height="${vh-2}" rx="1" fill="#40d8f0" opacity="0.75"/>` +
      `<rect x="${cx-vw/2+2}" y="${vy+1}" width="${(vw-4)/2}" height="${vh-2}" rx="1" fill="#60e8ff" opacity="0.3"/>` +
      `<rect x="${cx+vw/2}" y="${vy+1}" width="${3*s}" height="${2}" rx="1" fill="#2a3a4a"/>` +
      `<rect x="${cx-vw/2-3*s}" y="${vy+1}" width="${3*s}" height="${2}" rx="1" fill="#2a3a4a"/>`
    );
  }
};

// ── TORSO EQUIPMENT SVG GENERATORS ──
const TORSO_SVG_GEN = {
  plate_cuirass(r) {
    const {cx,cy,w,h} = r.torso; const s = r.scale;
    const tw = Math.round(w*s), th = Math.round(h*s);
    const x = cx-tw/2, y = cy-th/2;
    // Pauldrons
    const pw = Math.round(5*s), ph = Math.round(5*s);
    return _equipSvg(
      `<rect x="${x}" y="${y}" width="${tw}" height="${th}" rx="2" fill="#6a7888" stroke="#485060" stroke-width="1"/>` +
      `<rect x="${x+1}" y="${y+1}" width="${tw-2}" height="${3}" fill="rgba(180,200,220,0.3)"/>` +
      `<rect x="${cx-1}" y="${y}" width="${2}" height="${th}" fill="#586878" opacity="0.6"/>` +
      `<rect x="${x-pw/2}" y="${y-1}" width="${pw}" height="${ph}" rx="1" fill="#7a8898" stroke="#d4a828" stroke-width="0.8"/>` +
      `<rect x="${x+tw-pw/2}" y="${y-1}" width="${pw}" height="${ph}" rx="1" fill="#7a8898" stroke="#d4a828" stroke-width="0.8"/>` +
      `<rect x="${cx-3*s}" y="${y+th-4*s}" width="${6*s}" height="${3*s}" rx="1" fill="#586878"/>` +
      `<rect x="${x+2}" y="${y+th/2}" width="${3}" height="${2}" fill="#d4a828" opacity="0.5"/>` +
      `<rect x="${x+tw-5}" y="${y+th/2}" width="${3}" height="${2}" fill="#d4a828" opacity="0.5"/>`
    );
  },
  duster_coat(r) {
    const {cx,cy,w,h} = r.torso; const s = r.scale;
    const tw = Math.round(w*s*1.05), th = Math.round(h*s*1.3);
    const x = cx-tw/2, y = cy-th/2+1;
    return _equipSvg(
      `<rect x="${x}" y="${y}" width="${tw}" height="${th}" rx="1" fill="#5a3e28" stroke="#3a2618" stroke-width="0.8"/>` +
      `<rect x="${cx-1}" y="${y}" width="${2}" height="${th}" fill="#3a2618" opacity="0.5"/>` +
      `<rect x="${x+1}" y="${y+1}" width="${tw/2-2}" height="${2}" fill="#7a5838" opacity="0.4"/>` +
      `<rect x="${x+2}" y="${y+th*0.3}" width="${3}" height="${3}" rx="1" fill="#c8a870" opacity="0.6"/>` +
      `<rect x="${x+tw-5}" y="${y+th*0.3}" width="${3}" height="${3}" rx="1" fill="#c8a870" opacity="0.6"/>` +
      `<rect x="${x}" y="${y+th-4}" width="${tw/2-1}" height="${4}" rx="1" fill="#4a3220" opacity="0.5"/>` +
      `<rect x="${cx+1}" y="${y+th-4}" width="${tw/2-1}" height="${4}" rx="1" fill="#4a3220" opacity="0.5"/>`
    );
  },
  arcane_robes(r) {
    const {cx,cy,w,h} = r.torso; const s = r.scale;
    const tw = Math.round(w*s*1.1), th = Math.round((h+r.legs.h)*s*0.95);
    const x = cx-tw/2, y = cy-r.torso.h*s/2;
    return _equipSvg(
      `<path d="M${x+3} ${y} L${x-2} ${y+th} L${x+tw+2} ${y+th} L${x+tw-3} ${y} Z" fill="#22103a" stroke="#140828" stroke-width="1"/>` +
      `<path d="M${x+4} ${y+1} L${x} ${y+th-1} L${x+tw} ${y+th-1} L${x+tw-4} ${y+1} Z" fill="#2c1648" opacity="0.6"/>` +
      `<rect x="${cx-1}" y="${y}" width="${2}" height="${th}" fill="#6030a0" opacity="0.5"/>` +
      `<rect x="${x+1}" y="${y+th-3}" width="${tw-2}" height="${3}" fill="#6030a0" opacity="0.3"/>` +
      `<rect x="${x+2}" y="${y}" width="${2}" height="${th*0.7}" fill="#6030a0" opacity="0.25"/>` +
      `<rect x="${x+tw-4}" y="${y}" width="${2}" height="${th*0.7}" fill="#6030a0" opacity="0.25"/>` +
      `<rect x="${cx-2*s}" y="${y+3}" width="${4*s}" height="${3}" rx="1" fill="#8050c0" opacity="0.4"/>`
    );
  },
  holy_vestments(r) {
    const {cx,cy,w,h} = r.torso; const s = r.scale;
    const tw = Math.round(w*s*1.1), th = Math.round((h+r.legs.h)*s*0.95);
    const x = cx-tw/2, y = cy-r.torso.h*s/2;
    return _equipSvg(
      `<path d="M${x+3} ${y} L${x-1} ${y+th} L${x+tw+1} ${y+th} L${x+tw-3} ${y} Z" fill="#e8dcc8" stroke="#c8b898" stroke-width="0.8"/>` +
      `<path d="M${x+4} ${y+1} L${x+1} ${y+th-1} L${x+tw-1} ${y+th-1} L${x+tw-4} ${y+1} Z" fill="#f0e8d8" opacity="0.5"/>` +
      `<rect x="${cx-1}" y="${y}" width="${2}" height="${th}" fill="#d4a828" opacity="0.6"/>` +
      `<rect x="${x+1}" y="${y+th-3}" width="${tw-2}" height="${3}" fill="#d4a828" opacity="0.35"/>` +
      `<rect x="${x+2}" y="${y}" width="${2}" height="${th*0.6}" fill="#d4a828" opacity="0.3"/>` +
      `<rect x="${x+tw-4}" y="${y}" width="${2}" height="${th*0.6}" fill="#d4a828" opacity="0.3"/>` +
      `<rect x="${cx-2*s}" y="${y+2}" width="${4*s}" height="${4*s}" rx="1" fill="#38b8a0" opacity="0.5"/>` +
      `<rect x="${cx-1}" y="${y+4}" width="${2}" height="${2*s}" fill="#80e8d0" opacity="0.4"/>`
    );
  },
  tactical_vest(r) {
    const {cx,cy,w,h} = r.torso; const s = r.scale;
    const tw = Math.round(w*s), th = Math.round(h*s);
    const x = cx-tw/2, y = cy-th/2;
    return _equipSvg(
      `<rect x="${x}" y="${y}" width="${tw}" height="${th}" rx="2" fill="#2a3228" stroke="#1a2218" stroke-width="1"/>` +
      `<rect x="${x+1}" y="${y+1}" width="${tw/2-2}" height="${th-2}" rx="1" fill="#323e30" opacity="0.7"/>` +
      `<rect x="${cx+1}" y="${y+1}" width="${tw/2-2}" height="${th-2}" rx="1" fill="#323e30" opacity="0.7"/>` +
      `<rect x="${x-3*s}" y="${y}" width="${3*s}" height="${4*s}" rx="1" fill="#3a4438" stroke="#2a3228" stroke-width="0.7"/>` +
      `<rect x="${x+tw}" y="${y}" width="${3*s}" height="${4*s}" rx="1" fill="#3a4438" stroke="#2a3228" stroke-width="0.7"/>` +
      `<rect x="${x+2}" y="${y+th*0.5}" width="${4*s}" height="${3*s}" rx="1" fill="#3a4238" stroke="#1a2218" stroke-width="0.5"/>` +
      `<rect x="${x+tw-2-4*s}" y="${y+th*0.5}" width="${4*s}" height="${3*s}" rx="1" fill="#3a4238" stroke="#1a2218" stroke-width="0.5"/>` +
      `<rect x="${cx-1}" y="${y}" width="${2}" height="${th}" fill="#1a2218" opacity="0.4"/>`
    );
  }
};

// ── LEGS EQUIPMENT SVG GENERATORS ──
const LEGS_SVG_GEN = {
  plate_greaves(r) {
    const {cx,cy,w,h} = r.legs; const s = r.scale;
    const lw = Math.round(w*s*0.95), lh = Math.round(h*s);
    const x = cx-lw/2, y = cy-lh/2;
    const legW = Math.round(lw*0.38);
    return _equipSvg(
      `<rect x="${x}" y="${y}" width="${legW}" height="${lh}" rx="1" fill="#6a7888" stroke="#485060" stroke-width="0.8"/>` +
      `<rect x="${x+lw-legW}" y="${y}" width="${legW}" height="${lh}" rx="1" fill="#6a7888" stroke="#485060" stroke-width="0.8"/>` +
      `<rect x="${x}" y="${y+lh*0.3}" width="${legW}" height="${3*s}" rx="1" fill="#7a8a9a" stroke="#586878" stroke-width="0.5"/>` +
      `<rect x="${x+lw-legW}" y="${y+lh*0.3}" width="${legW}" height="${3*s}" rx="1" fill="#7a8a9a" stroke="#586878" stroke-width="0.5"/>` +
      `<rect x="${x+1}" y="${y+1}" width="${legW-2}" height="${2}" fill="rgba(180,200,220,0.3)"/>` +
      `<rect x="${x+lw-legW+1}" y="${y+1}" width="${legW-2}" height="${2}" fill="rgba(180,200,220,0.3)"/>`
    );
  },
  denim_pants(r) {
    const {cx,cy,w,h} = r.legs; const s = r.scale;
    const lw = Math.round(w*s), lh = Math.round(h*s);
    const x = cx-lw/2, y = cy-lh/2;
    const legW = Math.round(lw*0.4);
    return _equipSvg(
      `<rect x="${x}" y="${y}" width="${legW}" height="${lh}" rx="1" fill="#2a3448" stroke="#1a2030" stroke-width="0.7"/>` +
      `<rect x="${x+lw-legW}" y="${y}" width="${legW}" height="${lh}" rx="1" fill="#2a3448" stroke="#1a2030" stroke-width="0.7"/>` +
      `<rect x="${x}" y="${y}" width="${lw}" height="${3}" fill="#2a3448" stroke="#1a2030" stroke-width="0.5"/>` +
      `<rect x="${cx-1}" y="${y}" width="${2}" height="${3}" fill="#1a2030" opacity="0.5"/>` +
      `<rect x="${x+1}" y="${y+lh*0.6}" width="${2}" height="${2}" fill="#3a4860" opacity="0.4"/>` +
      `<rect x="${x+lw-legW+1}" y="${y+lh*0.5}" width="${2}" height="${2}" fill="#3a4860" opacity="0.4"/>`
    );
  },
  cargo_pants(r) {
    const {cx,cy,w,h} = r.legs; const s = r.scale;
    const lw = Math.round(w*s*1.05), lh = Math.round(h*s);
    const x = cx-lw/2, y = cy-lh/2;
    const legW = Math.round(lw*0.42);
    return _equipSvg(
      `<rect x="${x}" y="${y}" width="${legW}" height="${lh}" rx="1" fill="#2a3028" stroke="#1a2018" stroke-width="0.7"/>` +
      `<rect x="${x+lw-legW}" y="${y}" width="${legW}" height="${lh}" rx="1" fill="#2a3028" stroke="#1a2018" stroke-width="0.7"/>` +
      `<rect x="${x}" y="${y}" width="${lw}" height="${3}" fill="#2a3028" stroke="#1a2018" stroke-width="0.5"/>` +
      `<rect x="${cx-1}" y="${y}" width="${2}" height="${3}" fill="#1a2018" opacity="0.5"/>` +
      `<rect x="${x+legW-5*s}" y="${y+lh*0.35}" width="${4*s}" height="${3.5*s}" rx="1" fill="#323830" stroke="#1a2018" stroke-width="0.5"/>` +
      `<rect x="${x+lw-legW+1}" y="${y+lh*0.35}" width="${4*s}" height="${3.5*s}" rx="1" fill="#323830" stroke="#1a2018" stroke-width="0.5"/>` +
      `<rect x="${x}" y="${y+lh*0.55}" width="${legW}" height="${2.5*s}" rx="1" fill="#343c32" opacity="0.5"/>` +
      `<rect x="${x+lw-legW}" y="${y+lh*0.55}" width="${legW}" height="${2.5*s}" rx="1" fill="#343c32" opacity="0.5"/>`
    );
  }
};

// ── AUTO-POPULATE RACE-SPECIFIC EQUIPMENT SPRITES ──
(function populateRaceEquipment() {
  const headItems = ['plate_helm','wide_brim_hat','arcane_hood','gold_circlet','tactical_visor'];
  const torsoItems = ['plate_cuirass','duster_coat','arcane_robes','holy_vestments','tactical_vest'];
  const legsItems = ['plate_greaves','denim_pants','cargo_pants'];

  for (const [race, body] of Object.entries(RACE_BODY_REGIONS)) {
    // Generate head equipment
    for (const itemId of headItems) {
      const key = race + '_' + itemId;
      if (EQUIP_SPRITES[key]) continue; // don't overwrite pixel art
      const gen = HEAD_SVG_GEN[itemId];
      if (gen) EQUIP_SPRITES[key] = gen(body);
    }
    // Generate torso equipment
    for (const itemId of torsoItems) {
      const key = race + '_' + itemId;
      if (EQUIP_SPRITES[key]) continue;
      const gen = TORSO_SVG_GEN[itemId];
      if (gen) EQUIP_SPRITES[key] = gen(body);
    }
    // Generate legs equipment
    for (const itemId of legsItems) {
      const key = race + '_' + itemId;
      if (EQUIP_SPRITES[key]) continue;
      const gen = LEGS_SVG_GEN[itemId];
      if (gen) EQUIP_SPRITES[key] = gen(body);
    }
  }
})();

// ── UPDATE EQUIP_RACE_COMPAT — enable all body slots for races that now have sprites ──
(function updateRaceCompat() {
  // Races that previously only had weapon compat now get full body equipment
  const fullBodyRaces = [
    'zombie','skeleton','demon','succubus','angel','seraphim',
    'android','robot','mech','bigfoot','giant','reptilian','grey','martian'
  ];
  for (const race of fullBodyRaces) {
    if (RACE_BODY_REGIONS[race]) {
      // Race now has its own direct sprites — no fallback needed for body slots.
      // But keep the homosapien fallback for boots/hands that we didn't generate.
      const existing = EQUIP_RACE_COMPAT[race];
      if (existing) {
        // Upgrade to 'all' since we now have sprites for all slots
        existing.slots = 'all';
      } else {
        // Race had no compat entry — add one for boots + hands fallback
        EQUIP_RACE_COMPAT[race] = { fallback: 'homosapien', slots: 'all' };
      }
    }
  }
})();
